1	/**
2	 * doc-template-rows.test.ts — the default Word template keeps every row whole,
3	 * and repeats the header row of a table that runs onto the next page.
4	 *
5	 * Both are one attribute each away from being lost, and neither loss shows in the
6	 * template: the XML stays valid and the short tables in the default report fit on
7	 * one page either way, so the defect appears only in a document long enough to
8	 * split. What arrives then is a docx with no `w:cantSplit` and no `w:tblHeader`.
9	 *
10	 * The attribute that looks like it should do this does not: measured on a 150-row
11	 * table, `style:may-break-between-rows="false"` on the table exported `w:keepNext`
12	 * and no `w:cantSplit` at all. So the two attributes checked here are the ones the
13	 * template has to keep, and the check is on the source because a conversion cannot
14	 * run in this suite — LibreOffice is installed on demand by `docs/customer-doc`
15	 * and is deliberately absent from `environment.setup_commands`.
16	 */
17	import { describe, expect, test } from "bun:test";
18	import { readFileSync } from "node:fs";
19	
20	const TEMPLATE = "src/content/skills/docs/templates/report.fodt";
21	
22	describe("the default Word template's tables", () => {
23	  const xml = readFileSync(TEMPLATE, "utf8");
24	
25	  test("every row names a row style that keeps the row whole", () => {
26	    const rows = [...xml.matchAll(/<table:table-row\b[^>]*>/g)].map((match) => match[0]!);
27	    // Without this the loop below passes on a file whose tables were all renamed.
28	    expect(rows.length, `${TEMPLATE} must still contain table rows`).toBeGreaterThan(0);
29	
30	    for (const row of rows) {
31	      const style = row.match(/table:style-name="([^"]+)"/)?.[1];
32	      expect(style, `a row with no style may split mid-row: ${row}`).toBeTruthy();
33	
34	      const declaration = xml.match(new RegExp(`<style:style style:name="${style}" style:family="table-row">([\\s\\S]*?)</style:style>`))?.[1];
35	      expect(declaration, `row style "${style}" must be declared as a table-row style`).toBeTruthy();
36	      expect(declaration!, `row style "${style}" must carry fo:keep-together="always", or its rows split`).toContain('fo:keep-together="always"');
37	    }
38	  });
39	
40	  test("a table with a header row repeats it on the next page", () => {
41	    const tables = [...xml.matchAll(/<table:table\b[\s\S]*?<\/table:table>/g)].map((match) => match[0]!);
42	    expect(tables.length, `${TEMPLATE} must still contain tables`).toBeGreaterThan(0);
43	
44	    let withHeader = 0;
45	    for (const table of tables) {
46	      const firstRow = table.match(/<table:table-row\b[^>]*>[\s\S]*?<\/table:table-row>/)?.[0] ?? "";
47	      // A label/value table such as the title page's Meta has no header row to repeat.
48	      if (!firstRow.includes('table:style-name="CellHead"')) continue;
49	      withHeader += 1;
50	      expect(table, "a header row outside table:table-header-rows never repeats").toMatch(/<table:table-header-rows>\s*<table:table-row\b/);
51	    }
52	
53	    expect(withHeader, "no table declared a header row; check the CellHead style name").toBeGreaterThan(0);
54	  });
55	});

